+                *required_online_baseline_checkpoint_, baseline,
+                timeline_status_.last_coordinate))
+            return Status::failure(FailureCode::IdentityMismatch);
+    }
+    required_online_baseline_checkpoint_ = baseline;
+    return Status::success();
+}
